// trigger.cpp — external triggerbot
// Platform: Windows (x64), C++17, no third-party deps.
//
// Build (MSVC, x64 Native Tools prompt):
//   cl /std:c++17 /O2 /EHsc trigger.cpp user32.lib
// Build (MinGW-w64, incl. cross-compiling from macOS: brew install mingw-w64):
//   x86_64-w64-mingw32-g++ -std=c++17 -O2 -static trigger.cpp -o trigger.exe -luser32
//
// Run: start the game, then trigger.exe. Hold MOUSE4 to arm, END to quit.
// Every offset in `off::` is a placeholder — fill them from your own dump of
// the target build. The program refuses to run while core offsets are zero.

#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <tlhelp32.h>

#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <random>
#include <thread>

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
namespace cfg {
constexpr wchar_t kProcess[] = L"game.exe";   // target executable
constexpr wchar_t kModule[]  = L"client.dll"; // module the offsets are relative to

constexpr float kConePx      = 6.0f;          // radius around crosshair, in pixels
constexpr int   kDelayMinMs  = 40;            // reaction delay range
constexpr int   kDelayMaxMs  = 90;
constexpr int   kHoldMinMs   = 10;            // mouse-down duration range
constexpr int   kHoldMaxMs   = 25;
constexpr int   kCooldownMs  = 120;           // gap after a shot before re-arming
constexpr float kHeadHeight  = 64.0f;         // origin -> head, world units (Z-up)

constexpr int   kArmKey      = VK_XBUTTON1;   // hold to arm
constexpr int   kExitKey     = VK_END;
} // namespace cfg

namespace off {
// Module-relative statics
constexpr uintptr_t localPlayer  = 0x0;  // module + this -> local pawn pointer
constexpr uintptr_t entityList   = 0x0;  // module + this -> first entity pointer slot
constexpr uintptr_t viewMatrix   = 0x0;  // module + this -> float[16]
constexpr uintptr_t entityStride = 0x8;  // bytes between entity pointer slots
constexpr int       maxEntities  = 64;

// Pawn-relative fields
constexpr uintptr_t health       = 0x0;  // int32
constexpr uintptr_t team         = 0x0;  // int32
constexpr uintptr_t origin       = 0x0;  // float[3]
constexpr uintptr_t spottedMask  = 0x0;  // uint32, bit N set = visible to player index N
constexpr uintptr_t playerIndex  = 0x0;  // int32 on the local pawn, 0..31
} // namespace off

// ---------------------------------------------------------------------------
// Math
// ---------------------------------------------------------------------------
struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };
using Matrix4 = std::array<float, 16>;

// Row-major, D3D-style clip transform (Source-family layout). If projections
// land mirrored or off-screen, your engine stores it transposed: swap to
// column indexing (m[0], m[4], m[8], m[12] for row 0, etc.).
static bool worldToScreen(const Matrix4& m, const Vec3& p, float w, float h, Vec2& out) {
    const float cw = m[12] * p.x + m[13] * p.y + m[14] * p.z + m[15];
    if (cw < 0.01f) return false; // behind the camera

    const float cx = m[0] * p.x + m[1] * p.y + m[2]  * p.z + m[3];
    const float cy = m[4] * p.x + m[5] * p.y + m[6]  * p.z + m[7];

    out.x = (w * 0.5f) + (cx / cw) * (w * 0.5f);
    out.y = (h * 0.5f) - (cy / cw) * (h * 0.5f);
    return true;
}

// Squared distance from point c to segment ab, all in screen space.
static float distSqPointSegment(Vec2 c, Vec2 a, Vec2 b) {
    const float abx = b.x - a.x, aby = b.y - a.y;
    const float len2 = abx * abx + aby * aby;
    float t = 0.0f;
    if (len2 > 1e-6f) {
        t = ((c.x - a.x) * abx + (c.y - a.y) * aby) / len2;
        t = std::fmax(0.0f, std::fmin(1.0f, t));
    }
    const float px = a.x + t * abx - c.x;
    const float py = a.y + t * aby - c.y;
    return px * px + py * py;
}

// ---------------------------------------------------------------------------
// Process access
// ---------------------------------------------------------------------------
class Process {
public:
    ~Process() { if (handle_) CloseHandle(handle_); }

    bool attach(const wchar_t* exeName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return false;

        PROCESSENTRY32W pe{};
        pe.dwSize = sizeof(pe);
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
            if (_wcsicmp(pe.szExeFile, exeName) == 0) { pid_ = pe.th32ProcessID; break; }
        }
        CloseHandle(snap);
        if (!pid_) return false;

        handle_ = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid_);
        return handle_ != nullptr;
    }

    uintptr_t moduleBase(const wchar_t* moduleName) const {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid_);
        if (snap == INVALID_HANDLE_VALUE) return 0;

        uintptr_t base = 0;
        MODULEENTRY32W me{};
        me.dwSize = sizeof(me);
        for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me)) {
            if (_wcsicmp(me.szModule, moduleName) == 0) {
                base = reinterpret_cast<uintptr_t>(me.modBaseAddr);
                break;
            }
        }
        CloseHandle(snap);
        return base;
    }

    template <class T>
    T read(uintptr_t address) const {
        T value{};
        SIZE_T got = 0;
        if (!ReadProcessMemory(handle_, reinterpret_cast<LPCVOID>(address), &value, sizeof(T), &got) ||
            got != sizeof(T)) {
            return T{};
        }
        return value;
    }

    bool alive() const {
        DWORD code = 0;
        return handle_ && GetExitCodeProcess(handle_, &code) && code == STILL_ACTIVE;
    }

    DWORD pid() const { return pid_; }

private:
    DWORD  pid_    = 0;
    HANDLE handle_ = nullptr;
};

// Main top-level visible window owned by the target process.
static HWND findWindowForPid(DWORD pid) {
    struct Search { DWORD pid; HWND hwnd; } s{ pid, nullptr };
    EnumWindows([](HWND h, LPARAM lp) -> BOOL {
        auto* s = reinterpret_cast<Search*>(lp);
        DWORD owner = 0;
        GetWindowThreadProcessId(h, &owner);
        if (owner == s->pid && IsWindowVisible(h) && GetWindow(h, GW_OWNER) == nullptr) {
            s->hwnd = h;
            return FALSE;
        }
        return TRUE;
    }, reinterpret_cast<LPARAM>(&s));
    return s.hwnd;
}

// ---------------------------------------------------------------------------
// Trigger logic
// ---------------------------------------------------------------------------
// True if any live, visible enemy's feet-to-head line passes within kConePx
// of the screen centre.
static bool enemyInCone(const Process& proc, uintptr_t base, float w, float h) {
    const uintptr_t local = proc.read<uintptr_t>(base + off::localPlayer);
    if (!local) return false;

    const int localTeam  = proc.read<int32_t>(local + off::team);
    const int localIndex = proc.read<int32_t>(local + off::playerIndex);
    if (localIndex < 0 || localIndex > 31) return false;

    const Matrix4 vm = proc.read<Matrix4>(base + off::viewMatrix);
    const Vec2 centre{ w * 0.5f, h * 0.5f };
    const float coneSq = cfg::kConePx * cfg::kConePx;

    for (int i = 0; i < off::maxEntities; ++i) {
        const uintptr_t ent = proc.read<uintptr_t>(base + off::entityList + i * off::entityStride);
        if (!ent || ent == local) continue;

        if (proc.read<int32_t>(ent + off::health) <= 0) continue;
        if (proc.read<int32_t>(ent + off::team) == localTeam) continue;

        const uint32_t spotted = proc.read<uint32_t>(ent + off::spottedMask);
        if (!(spotted & (1u << localIndex))) continue; // no line of sight

        const Vec3 feet = proc.read<Vec3>(ent + off::origin);
        const Vec3 head{ feet.x, feet.y, feet.z + cfg::kHeadHeight };

        Vec2 sFeet{}, sHead{};
        if (!worldToScreen(vm, feet, w, h, sFeet)) continue;
        if (!worldToScreen(vm, head, w, h, sHead)) continue;

        if (distSqPointSegment(centre, sFeet, sHead) <= coneSq) return true;
    }
    return false;
}

static void sendClick(std::mt19937& rng) {
    std::uniform_int_distribution<int> hold(cfg::kHoldMinMs, cfg::kHoldMaxMs);

    INPUT down{};
    down.type = INPUT_MOUSE;
    down.mi.dwFlags = MOUSEEVENTF_LEFTDOWN;
    INPUT up = down;
    up.mi.dwFlags = MOUSEEVENTF_LEFTUP;

    SendInput(1, &down, sizeof(INPUT));
    std::this_thread::sleep_for(std::chrono::milliseconds(hold(rng)));
    SendInput(1, &up, sizeof(INPUT));
}

static bool offsetsConfigured() {
    return off::localPlayer && off::entityList && off::viewMatrix &&
           off::health && off::team && off::origin && off::spottedMask;
}

static bool keyDown(int vk) { return (GetAsyncKeyState(vk) & 0x8000) != 0; }

int main() {
    if (!offsetsConfigured()) {
        std::fprintf(stderr, "[!] offsets in namespace off are still zero; fill them in and rebuild.\n");
        return 1;
    }

    Process proc;
    std::printf("[*] waiting for %ls...\n", cfg::kProcess);
    while (!proc.attach(cfg::kProcess)) {
        if (keyDown(cfg::kExitKey)) return 0;
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
    std::printf("[+] attached, pid %lu\n", static_cast<unsigned long>(proc.pid()));

    uintptr_t base = 0;
    while (!(base = proc.moduleBase(cfg::kModule))) {
        if (keyDown(cfg::kExitKey) || !proc.alive()) return 0;
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }
    std::printf("[+] %ls @ 0x%llx\n", cfg::kModule, static_cast<unsigned long long>(base));

    HWND window = nullptr;
    while (!(window = findWindowForPid(proc.pid()))) {
        if (keyDown(cfg::kExitKey) || !proc.alive()) return 0;
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }
    std::printf("[+] ready. hold MOUSE4 to arm, END to quit.\n");

    std::mt19937 rng{ std::random_device{}() };
    std::uniform_int_distribution<int> reaction(cfg::kDelayMinMs, cfg::kDelayMaxMs);

    timeBeginPeriod_guard:; // (no winmm dependency; Sleep granularity is fine at 1ms polls on modern Windows)

    while (!keyDown(cfg::kExitKey) && proc.alive()) {
        std::this_thread::sleep_for(std::chrono::milliseconds(1));

        if (!keyDown(cfg::kArmKey)) continue;
        if (GetForegroundWindow() != window) continue;

        RECT rc{};
        if (!GetClientRect(window, &rc)) continue;
        const float w = static_cast<float>(rc.right - rc.left);
        const float h = static_cast<float>(rc.bottom - rc.top);
        if (w <= 0 || h <= 0) continue;

        if (!enemyInCone(proc, base, w, h)) continue;

        std::this_thread::sleep_for(std::chrono::milliseconds(reaction(rng)));

        // Target may have left the cone during the delay — confirm before firing.
        if (!keyDown(cfg::kArmKey) || !enemyInCone(proc, base, w, h)) continue;

        sendClick(rng);
        std::this_thread::sleep_for(std::chrono::milliseconds(cfg::kCooldownMs));
    }

    std::printf("[*] exiting.\n");
    return 0;
}
